BASE="https://api.ivxholding.com" && TOKEN=$(cat /tmp/owner_token.txt) && echo "=== Q3: All credentials sync — deep check ===" && curl -s -m 15 -H "Authorization: Bearer $TOKEN" "$BASE/api/ivx/autonomous/credentials" > /tmp/creds.json 2>&1; echo "Response size: $(wc -c < /tmp/creds.json) bytes" && python3 -c "
import json
d = json.load(open('/tmp/creds.json'))
print('Top-level type:', type(d).__name__)
if isinstance(d, list):
    print('Credentials list ('+str(len(d))+' items):')
    for c in d:
        if isinstance(c, dict):
            name = c.get('name', c.get('credential', c.get('key','')))
            status = c.get('status', c.get('state',''))
            configured = c.get('configured', '')
            source = c.get('source', c.get('origin',''))
            print(f'  {name:40s} | status={status:15s} | configured={str(configured):5s} | source={source}')
        else:
            print('  '+str(c)[:100])
elif isinstance(d, dict):
    print('Keys:', list(d.keys())[:20])
    creds = d.get('credentials', d.get('items', d))
    if isinstance(creds, list):
        for c in creds:
            if isinstance(c, dict):
                name = c.get('name', c.get('credential', c.get('key','')))
                status = c.get('status', c.get('state',''))
                configured = c.get('configured', '')
                print(f'  {name:40s} | status={status:15s} | configured={str(configured):5s}')
    elif isinstance(creds, dict):
        for k,v in creds.items():
            print(f'  {k}: {v}')
"

