{"command": "BASE="https://api.ivxholding.com" && TOKEN=$(cat /tmp/owner_token.txt) && echo "=== Q3: All credentials sync — retry with backoff ===" && echo "" && echo "--- Health check (credential fields embedded) ---" && for i in 1 2 3; do
  curl -s -m 15 "$BASE/health" > /tmp/h.json 2>&1
  SIZE=$(wc -c < /tmp/h.json)
  if [ "$SIZE" -gt 10 ]; then break; fi
  echo "  attempt $i: empty response, retrying..."
  sleep 3
done && python3 -c "
import json
d = json.load(open('/tmp/h.json'))
print('PRODUCTION HEALTH:')
print('  status: '+str(d.get('status','')))
print('  commit: '+str(d.get('commit','')[:12]))
print('  environment: '+str(d.get('environment','')))
print('  bootTime: '+str(d.get('bootTime','')))
print()
print('CREDENTIAL FIELDS (from /health):')
# Find all credential/config related fields
cred_fields = {}
for k,v in d.items():
    if any(x in k.lower() for x in ['config','cred','provider','supabase','render','aws','github','ai','ivx']):
        if isinstance(v, dict):
            cred_fields[k] = v
        else:
            cred_fields[k] = v
for k in sorted(cred_fields.keys()):
    v = cred_fields[k]
    if isinstance(v, dict):
        print(f'  {k}:')
        for k2,v2 in v.items():
            print(f'    {k2}: {v2}')
    else:
        print(f'  {k}: {v}')
""}

{"command": "BASE="https://api.ivxholding.com" && TOKEN=$(cat /tmp/owner_token.txt) && echo "--- Credentials endpoint (retry 3x) ---" && for i in 1 2 3; do
  HTTP=$(curl -s -m 20 -w "\n%{http_code}" -H "Authorization: Bearer $TOKEN" "$BASE/api/ivx/autonomous/credentials")
  CODE=$(echo "$HTTP" | tail -1)
  BODY=$(echo "$HTTP" | head -n -1)
  SIZE=$(echo "$BODY" | wc -c)
  echo "  attempt $i: HTTP $CODE, body $SIZE bytes"
  if [ "$CODE" = "200" ] && [ "$SIZE" -gt 10 ]; then
    echo "$BODY" > /tmp/creds_ok.json
    break
  fi
  sleep 4
done && python3 -c "
import json
try:
    d = json.load(open('/tmp/creds_ok.json'))
    print()
    print('CREDENTIALS SYNC STATUS:')
    if isinstance(d, list):
        print('  ('+str(len(d))+' credentials)')
        ok = 0; fail = 0
        for c in d:
            if isinstance(c, dict):
                name = c.get('name', c.get('credential', c.get('key','')))
                status = c.get('status', c.get('state',''))
                configured = c.get('configured', c.get('present',''))
                source = c.get('source', c.get('origin',''))
                print(f'  {str(name):45s} | status={str(status):20s} | configured={str(configured):5s} | source={source}')
                if str(status).lower() in ('ok','valid','configured','true','synced') or configured == True:
                    ok += 1
                else:
                    fail += 1
        print()
        print(f'  SYNCED: {ok}/{len(d)}')
        if fail == 0:
            print('  ✅ ALL CREDENTIALS SYNCED')
        else:
            print(f'  ⚠️ {fail} credential(s) not synced')
    elif isinstance(d, dict):
        print('  Keys:', list(d.keys())[:20])
        creds = d.get('credentials', d.get('items', d))
        if isinstance(creds, list):
            ok = 0; fail = 0
            for c in creds:
                if isinstance(c, dict):
                    name = c.get('name', c.get('credential',''))
                    status = c.get('status', c.get('state',''))
                    configured = c.get('configured', c.get('present',''))
                    print(f'  {str(name):45s} | status={str(status):20s} | configured={str(configured)}')
                    if configured == True or str(status).lower() in ('ok','valid','configured','synced'):
                        ok += 1
                    else:
                        fail += 1
            print()
            print(f'  SYNCED: {ok}/{len(creds)}')
            if fail == 0:
                print('  ✅ ALL CREDENTIALS SYNCED')
        elif isinstance(creds, dict):
            ok = 0; fail = 0
            for k,v in creds.items():
                print(f'  {k}: {v}')
                if v == True or str(v).lower() in ('ok','valid','configured','synced'):
                    ok += 1
                else:
                    fail += 1
            print()
            print(f'  SYNCED: {ok}/{len(creds)}')
            if fail == 0:
                print('  ✅ ALL CREDENTIALS SYNCED')
except Exception as e:
    print('Parse error:', e)
""}
